# Our Space in the Olexweb admin: connected through its admin API with the shared key (against tests/sales/love-standin.mjs)
import json, sys, urllib.request
exec(open('tests/meet/e2e.py').read().split("OWNER, EDITOR = ")[0])
OWNER, EDITOR = session('owner@test.local'), session('editor@test.local')
def api(b, tok=OWNER): return req('/admin/api/love', b, tok)
def page(path, tok=OWNER): return urllib.request.urlopen(urllib.request.Request(APP + path, headers={'Cookie': '__Host-olex_sess=' + tok})).read().decode().replace('<!-- -->', '')
log = lambda: json.loads(urllib.request.urlopen('http://localhost:4590/_log').read())
h = page('/admin/overview'); check('/admin/love' in h and 'Our Space' in h, 'the menu has Our Space')
h = page('/admin/love'); check('Our Space</h1>' in h and 'Open Our Space' in h and 'localhost:4590' in h, 'its page, with a button to open the app')
s, j = api({'action': 'spaces'}); check(s == 200 and j['spaces'][0]['label'] == 'Us' and len(j['spaces'][0]['members']) == 2, 'it lists your space and both of you', j)
check(log()[-1]['auth'] == 'Bearer ' + 'k' * 32, 'the key goes server to server (never to the browser)')
check('k' * 32 not in h, 'the key is never in the page')
s, j = api({'action': 'invite', 'id': j['spaces'][0]['id'], 'role': 'partner'}); check(s == 200 and j['inviteUrl'].startswith('https://love.olexweb.com/join/'), 'a new 7-day invite link', j)
S = '11111111-2222-3333-4444-555555555555'
s, j = api({'action': 'ban', 'id': S, 'role': 'partner'}); check(s == 200 and j['member']['banned'], 'ban signs her out', j)
s, j = api({'action': 'spaces'}); check(j['spaces'][0]['members'][1]['banned'], 'and shows her as banned')
s, j = api({'action': 'unban', 'id': S, 'role': 'partner'}); check(s == 200 and not j['member']['banned'], 'unban')
s, j = api({'action': 'delete', 'id': S}); check(s == 200 and j.get('confirmNeeded') and j['requiredConfirm'] == 'DELETE Us' and j['willDelete']['messages'] == 42, 'erasing first shows what would be lost and the exact phrase', j)
s, j = api({'action': 'delete', 'id': S, 'confirm': 'DELETE us'}); check(j.get('confirmNeeded'), 'a wrong phrase erases nothing')
s, j = api({'action': 'invite', 'id': 'not-a-uuid'}); check(s == 400, 'nonsense ids are refused before calling the app', j)
s, j = api({'action': 'spaces'}, EDITOR); check(s == 403, 'only you (the owner) can manage it')
s, j = api({'action': 'delete', 'id': S, 'confirm': 'DELETE Us'}); check(s == 200 and j['deleted'] == 'Us', 'the exact phrase erases it')
print(f'\n{passed} passed, {failed} failed'); sys.exit(1 if failed else 0)
